const SGEO = {
  ready:false, sc:1, get DATA(){ return SILV_DATA; },
  dec(s){ return MGEO.dec(s); },
  pathRaw(){
    if(this._raw) return this._raw;
    const p = this.dec(this.DATA.path), out = [];
    let x = 0, y = 0;
    for(let i = 0; i < p.length; i += 2){ x += p[i]; y += p[i + 1]; out.push([x / 10, y / 10]); }
    // OpenStreetMap marks Village as an estimate, and it comes out as a kink
    // tighter than the Loop: ease that one corner out to its real radius
    // the survey's straights are single long edges; cut them up so they can bend
    { const d = []; for(let i = 0; i < out.length; i++){ const a = out[i], b = out[(i + 1) % out.length];
        const k = Math.max(1, Math.ceil(Math.hypot(b[0] - a[0], b[1] - a[1]) / 4));
        for(let j = 0; j < k; j++) d.push([a[0] + (b[0] - a[0]) * j / k, a[1] + (b[1] - a[1]) * j / k]); }
      out.length = 0; out.push(...d); }
    const n = out.length, cum = [0];
    for(let i = 1; i < n; i++) cum.push(cum[i - 1] + Math.hypot(out[i][0] - out[i - 1][0], out[i][1] - out[i - 1][1]));
    const Lp = cum[n - 1], i0 = cum.findIndex(v => v > Lp * 0.112), i1 = cum.findIndex(v => v > Lp * 0.140);
    for(let pass = 0; pass < 160; pass++){
      const c = out.map(q => q.slice());
      for(let i = i0 + 1; i < i1; i++){
        const a = c[i - 1], b = c[i + 1], w = 0.5 * Math.min(1, (i - i0) / 12, (i1 - i) / 12);
        out[i][0] += w * ((a[0] + b[0]) / 2 - c[i][0]); out[i][1] += w * ((a[1] + b[1]) / 2 - c[i][1]);
      }
    }
    return (this._raw = out);
  },
  // the lap's height: the survey, with the small things the survey cannot see
  elev(u){
    if(!this._ef){
      const f = elevMC(this.DATA.elev);
      this._ef = u => f(u)
        + 0.10 * bumpU(u, 0.040, 0.004)                    // the bump on the apex of Abbey
        + 0.35 * bumpU(u, 0.828, 0.010)                    // the little crest into Stowe
        - 0.06 * bumpU(u, 0.884, 0.006) + 0.05 * bumpU(u, 0.892, 0.004);   // bumpy, downhill braking into Vale
    }
    return this._ef(u);
  },
  rings(str, q){
    const a = this.dec(str), out = [], sc = this.sc;
    let i = 0, px = 0, py = 0;
    while(i < a.length){
      const n = a[i++], r = [];
      for(let k = 0; k < n; k++){ px += a[i++]; py += a[i++]; r.push([px / q * sc, py / q * sc]); }
      out.push(r);
    }
    return out;
  },
  init(sc){
    if(this.ready && this.sc === sc) return this;
    const D = this.DATA, q = D.q; this.sc = sc;
    this.land = {}; for(const k in D.land) this.land[k] = this.rings(D.land[k], q);
    this.lines = {}; for(const k in D.lines) this.lines[k] = this.rings(D.lines[k], q);
    this.roads = {}; for(const k in D.roads) this.roads[k] = this.rings(D.roads[k], q);
    const b = this.dec(D.bld); this.blds = [];
    const LM = this.LM || ["", "wing", "brdc", "museum", "paddock", "experience", "media", "hotel"];
    let i = 0, px = 0, py = 0;
    while(i < b.length){
      const n = b[i++], h = b[i++], kind = b[i++], lm = LM[b[i++]] || "", st = b[i++];
      const pts = [];
      for(let k = 0; k < n; k++){ px += b[i++]; py += b[i++]; pts.push([px / q * sc, py / q * sc]); }
      this.blds.push({ pts, h, kind, lm, stand:st ? D.stands[st - 1] : "" });
    }
    const t = this.dec(D.trees); this.trees = [];
    { let x = 0, y = 0; for(let k = 0; k < t.length; k += 2){ x += t[k]; y += t[k + 1]; this.trees.push([x * sc, y * sc]); } }
    const G = D.dem; this.demG = { N:G.N, X0:G.X0, ST:G.ST, h:Float32Array.from(this.dec(G.h), v => v / 10) };
    this.ready = true;
    return this;
  },
  // the surveyed ground, before the circuit is cut in, on the lap's height scale
  dem(x, y){
    const g = this.demG, s = this.sc;
    const fx = clamp((x / s - g.X0) / g.ST, 0, g.N - 1.001), fy = clamp((y / s - g.X0) / g.ST, 0, g.N - 1.001);
    const c = Math.floor(fx), r = Math.floor(fy), a = fx - c, bb = fy - r, H = g.h, N = g.N;
    // smoothstep the cell, so the 100 m grid reads as rolling ground and not as facets
    const sa = a * a * (3 - 2 * a), sb = bb * bb * (3 - 2 * bb);
    return H[r * N + c] * (1 - sa) * (1 - sb) + H[r * N + c + 1] * sa * (1 - sb) +
           H[(r + 1) * N + c] * (1 - sa) * sb + H[(r + 1) * N + c + 1] * sa * sb;
  },
};


export { SGEO };
